import os
from langchain_openai import ChatOpenAI
from browser_use import Agent
import gradio as gr
from typing import Callable
import asyncio

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str):
    async def fn(message, history):
        inputs = preprocess(message, history)

        agent = Agent(
            task=inputs["message"],
            llm=ChatOpenAI(
                api_key=api_key,
                model=model_name,
                disabled_params={"parallel_tool_calls": None}
            ),
            use_vision=(model_name != "o3-mini-2025-01-31")  # Only disable vision for o3-mini
        )

        try:
            result = await agent.run()
            return postprocess(result)
        except Exception as e:
            return f"Error: {str(e)}"

    return fn  # Remove sync_wrapper, return async function directly

def get_interface_args(pipeline):
    if pipeline == "browser":
        def preprocess(message, history):
            return {"message": message}

        def postprocess(result):
            if hasattr(result, 'all_results') and hasattr(result, 'all_model_outputs'):
                # Get the thought process from non-final results
                thoughts = [r.extracted_content for r in result.all_results if not r.is_done]
                # Get the final answer from the last result
                final_answer = next((r.extracted_content for r in reversed(result.all_results) if r.is_done), None)

                if final_answer:
                    # Return in Gradio's message format
                    return {
                        "role": "assistant",
                        "content": final_answer,
                        "metadata": {
                            "title": "🔍 " + " → ".join(thoughts)
                        }
                    }

            # Fallback to simple message format
            return {
                "role": "assistant",
                "content": str(result) if not isinstance(result, str) else result
            }

        return preprocess, postprocess
    else:
        raise ValueError(f"Unsupported pipeline type: {pipeline}")

def registry(name: str, token: str | None = None, **kwargs):
    api_key = token or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("OPENAI_API_KEY environment variable is not set.")

    pipeline = "browser"
    preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, api_key)

    # Remove title and description from kwargs if they exist
    kwargs.pop('title', None)
    kwargs.pop('description', None)

    interface = gr.ChatInterface(
        fn=fn,
        title="Browser Use Agent",
        description="Chat with an AI agent that can perform browser tasks.",
        examples=["Go to amazon.com and find the best rated laptop and return the price.", 
                 "Find the current weather in New York"],
        **kwargs
    )

    return interface

from smolagents import CodeAgent, DuckDuckGoSearchTool, HfApiModel
from smolagents.agents import ActionStep
import gradio as gr
from typing import Generator, List, Dict

def create_agent(model_name: str = None):
    model = HfApiModel(model_name) if model_name else HfApiModel()
    return CodeAgent(tools=[DuckDuckGoSearchTool()], model=model)

def stream_agent_response(agent: CodeAgent, prompt: str) -> Generator[Dict, None, None]:
    # First yield the thinking message
    yield {
        "role": "assistant",
        "content": "Let me think about that...",
        "metadata": {"title": "🤔 Thinking"}
    }

    # Run the agent and capture its response
    try:
        # Get the agent's response
        for step in agent.run(prompt, stream=True):
            if isinstance(step, ActionStep):
                # Show LLM output if present (as collapsible thought)
                if step.llm_output:
                    yield {
                        "role": "assistant",
                        "content": step.llm_output,
                        "metadata": {"title": "🧠 Thought Process"}
                    }

                # Show tool call if present
                if step.tool_call:
                    content = step.tool_call.arguments
                    if step.tool_call.name == "python_interpreter":
                        content = f"```python\n{content}\n```"
                    yield {
                        "role": "assistant",
                        "content": str(content),
                        "metadata": {"title": f"🛠️ Using {step.tool_call.name}"}
                    }

                # Show observations if present
                if step.observations:
                    yield {
                        "role": "assistant",
                        "content": f"```\n{step.observations}\n```",
                        "metadata": {"title": "👁️ Observations"}
                    }

                # Show errors if present
                if step.error:
                    yield {
                        "role": "assistant",
                        "content": str(step.error),
                        "metadata": {"title": "❌ Error"}
                    }

                # Show final output if present (without metadata to keep it expanded)
                if step.action_output is not None and not step.error:
                    # Only show the final output if it's actually the last step
                    if step == step.action_output:
                        yield {
                            "role": "assistant",
                            "content": str(step.action_output)
                        }
            else:
                # For any other type of step output
                yield {
                    "role": "assistant",
                    "content": str(step),
                    "metadata": {"title": "🔄 Processing"}
                }

    except Exception as e:
        yield {
            "role": "assistant",
            "content": f"Error: {str(e)}",
            "metadata": {"title": "❌ Error"}
        }

async def interact_with_agent(message: str, history: List, model_name: str = None) -> Generator[List, None, None]:
    # Add user message
    history.append({"role": "user", "content": message})
    yield history

    # Create agent instance with specified model
    agent = create_agent(model_name)

    # Stream agent responses
    for response in stream_agent_response(agent, message):
        history.append(response)
        yield history

