import os
import cohere
import gradio as gr
from typing import Callable
import base64

__version__ = "0.0.3"


def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str):
    def fn(message, history):
        inputs = preprocess(message, history)
        client = cohere.Client(api_key=api_key)
        stream = client.chat_stream(
            model=model_name,
            message=inputs["message"],
            chat_history=inputs["chat_history"],
        )
        response_text = ""
        for chunk in stream:
            if chunk.event_type == "text-generation":
                delta = chunk.text
                response_text += delta
                yield postprocess(response_text)

    return fn


def get_image_base64(url: str, ext: str):
    with open(url, "rb") as image_file:
        encoded_string = base64.b64encode(image_file.read()).decode('utf-8')
    return "data:image/" + ext + ";base64," + encoded_string


def handle_user_msg(message: str):
    if type(message) is str:
        return message
    elif type(message) is dict:
        if message["files"] is not None and len(message["files"]) > 0:
            ext = os.path.splitext(message["files"][-1])[1].strip(".")
            if ext.lower() in ["png", "jpg", "jpeg", "gif", "pdf"]:
                encoded_str = get_image_base64(message["files"][-1], ext)
            else:
                raise NotImplementedError(f"Not supported file type {ext}")
            return {
                "message": message["text"],
                "attachments": [
                    {
                        "source": encoded_str,
                        "type": "image",
                    }
                ]
            }
        else:
            return message["text"]
    else:
        raise NotImplementedError


def get_interface_args(pipeline):
    if pipeline == "chat":
        inputs = None
        outputs = None

        def preprocess(message, history):
            chat_history = []
            files = None
            for user_msg, assistant_msg in history:
                if assistant_msg is not None:
                    chat_history.append({"role": "USER", "message": handle_user_msg(user_msg)})
                    chat_history.append({"role": "ASSISTANT", "message": assistant_msg})
                else:
                    files = user_msg
            if type(message) is str and files is not None:
                message = {"text": message, "files": files}
            elif type(message) is dict and files is not None:
                if message["files"] is None or len(message["files"]) == 0:
                    message["files"] = files

            return {
                "message": handle_user_msg(message),
                "chat_history": chat_history
            }

        postprocess = lambda x: x
    else:
        # Add other pipeline types when they will be needed
        raise ValueError(f"Unsupported pipeline type: {pipeline}")
    return inputs, outputs, preprocess, postprocess


def get_pipeline(model_name):
    # Determine the pipeline type based on the model name
    # For simplicity, assuming all models are chat models at the moment
    return "chat"


def registry(name: str, token: str | None = None, **kwargs):
    """
    Create a Gradio Interface for a model on Cohere.

    Parameters:
        - name (str): The name of the Cohere model.
        - token (str, optional): The API key for Cohere.
    """
    api_key = token or os.environ.get("COHERE_API_KEY")
    if not api_key:
        raise ValueError("COHERE_API_KEY environment variable is not set.")

    pipeline = get_pipeline(name)
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, api_key)

    if pipeline == "chat":
        interface = gr.ChatInterface(fn=fn, multimodal=True, **kwargs)
    else:
        # For other pipelines, create a standard Interface (not implemented yet)
        interface = gr.Interface(fn=fn, inputs=inputs, outputs=outputs, **kwargs)

    return interface

import os
from lumaai import LumaAI
import gradio as gr
from typing import Callable
import base64
import time

__version__ = "0.0.3"


def get_fn(preprocess: Callable, postprocess: Callable, api_key: str, pipeline: str):
    def fn(message, history, generation_type):
        try:
            inputs = preprocess(message, history)
            # Create a fresh client instance for each generation
            client = LumaAI(auth_token=api_key)

            # Validate generation type
            if generation_type not in ["video", "image"]:
                raise ValueError(f"Invalid generation type: {generation_type}")

            try:
                if generation_type == "video":
                    generation = client.generations.create(
                        prompt=inputs["prompt"],
                        **inputs.get("additional_params", {})
                    )
                else:  # image
                    generation = client.generations.image.create(
                        prompt=inputs["prompt"],
                        **inputs.get("additional_params", {})
                    )
            except Exception as e:
                raise RuntimeError(f"Failed to create generation: {str(e)}")

            # Poll for completion with timeout
            start_time = time.time()
            timeout = 300  # 5 minutes timeout

            while True:
                if time.time() - start_time > timeout:
                    raise RuntimeError("Generation timed out after 5 minutes")

                try:
                    generation = client.generations.get(id=generation.id)
                    if generation.state == "completed":
                        asset_url = generation.assets.video if generation_type == "video" else generation.assets.image
                        break
                    elif generation.state == "failed":
                        raise RuntimeError(f"Generation failed: {generation.failure_reason}")
                    time.sleep(3)
                    yield f"Generating {generation_type}... (Status: {generation.state})"
                except Exception as e:
                    raise RuntimeError(f"Error checking generation status: {str(e)}")

            # Return asset URL wrapped in appropriate format for display
            yield postprocess(asset_url, generation_type)

        except Exception as e:
            yield f"Error: {str(e)}"
            raise

    return fn


def get_image_base64(url: str, ext: str):
    with open(url, "rb") as image_file:
        encoded_string = base64.b64encode(image_file.read()).decode('utf-8')
    return "data:image/" + ext + ";base64," + encoded_string


def handle_user_msg(message: str):
    if type(message) is str:
        return message
    elif type(message) is dict:
        if message["files"] is not None and len(message["files"]) > 0:
            ext = os.path.splitext(message["files"][-1])[1].strip(".")
            if ext.lower() in ["png", "jpg", "jpeg", "gif", "pdf"]:
                encoded_str = get_image_base64(message["files"][-1], ext)
            else:
                raise NotImplementedError(f"Not supported file type {ext}")
            content = [
                    {"type": "text", "text": message["text"]},
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": encoded_str,
                        }
                    },
                ]
        else:
            content = message["text"]
        return content
    else:
        raise NotImplementedError


def get_interface_args(pipeline):
    generation_type = gr.Dropdown(
        choices=["video", "image"], 
        label="Generation Type", 
        value="video" if pipeline == "video" else "image"
    )
    outputs = None

    def preprocess(message, history):
        if isinstance(message, str):
            return {"prompt": message}
        elif isinstance(message, dict):
            prompt = message.get("text", "")
            additional_params = {}

            # Handle optional parameters
            if message.get("aspect_ratio"):
                additional_params["aspect_ratio"] = message["aspect_ratio"]
            if message.get("model"):
                additional_params["model"] = message["model"]

            return {
                "prompt": prompt,
                "additional_params": additional_params
            }

    def postprocess(url, generation_type):
        if generation_type == "video":
            return f'<video width="100%" controls><source src="{url}" type="video/mp4">Your browser does not support the video tag.</video>'
        else:
            return f"![Generated Image]({url})"

    return generation_type, outputs, preprocess, postprocess


def get_pipeline(model_name):
    # Support both video and image pipelines
    return "video" if model_name == "dream-machine" else "image"


def registry(name: str = "dream-machine", token: str = None, **kwargs):
    """
    Create a Gradio Interface for LumaAI generation.

    Parameters:
        - name (str): Model name (defaults to 'dream-machine' for video, use 'photon-1' or 'photon-flash-1' for images)
        - token (str, optional): The API key for LumaAI
        - **kwargs: Additional keyword arguments passed to gr.Interface
    """
    api_key = token or kwargs.pop('api_key', None) or os.environ.get("LUMAAI_API_KEY")
    if not api_key:
        raise ValueError("API key must be provided either through token parameter, kwargs, or LUMAAI_API_KEY environment variable.")

    pipeline = get_pipeline(name)
    generation_type, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(preprocess, postprocess, api_key, pipeline)

    interface = gr.ChatInterface(
        fn=fn,
        additional_inputs=[generation_type],
        type="messages",
        title="LumaAI Generation",
        description="Generate videos or images from text prompts using LumaAI",
        **kwargs
    )

    return interface

import os
from openai import OpenAI
import gradio as gr
from typing import Callable
import base64
import re
import modelscope_studio.components.base as ms
import modelscope_studio.components.legacy as legacy
import modelscope_studio.components.antd as antd

# Constants for coder interface
SystemPrompt = """You are an expert web developer specializing in creating clean, efficient, and modern web applications.
Your task is to write complete, self-contained HTML files that include all necessary CSS and JavaScript.
Focus on:
- Writing clear, maintainable code
- Following best practices
- Creating responsive designs
- Adding appropriate styling and interactivity
Return only the complete HTML code without any additional explanation."""

DEMO_LIST = [
    {
        "card": {"index": 0},
        "title": "Simple Button",
        "description": "Create a button that changes color when clicked"
    },
    {
        "card": {"index": 1},
        "title": "Todo List",
        "description": "Create a simple todo list with add/remove functionality"
    },
    {
        "card": {"index": 2},
        "title": "Timer App",
        "description": "Create a countdown timer with start/pause/reset controls"
    }
]

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str, base_url: str = None):
    def fn(message, history):
        inputs = preprocess(message, history)

        client = OpenAI(
            api_key=api_key,
            base_url="https://api.hyperbolic.xyz/v1"
        )

        completion = client.chat.completions.create(
            model=model_name,
            messages=[
                *inputs["messages"]
            ],
            stream=True,
            temperature=0.7,
            max_tokens=512,
            top_p=0.9,
        )
        response_text = ""
        for chunk in completion:
            delta = chunk.choices[0].delta.content or ""
            # Replace DeepSeek-R1 special tokens
            if "deepseek" in model_name.lower():
                delta = delta.replace("<think>", "[think]").replace("</think>", "[/think]")
            response_text += delta
            yield postprocess(response_text)

    return fn


def get_interface_args(pipeline):
    if pipeline == "chat":
        inputs = None
        outputs = None

        def preprocess(message, history):
            messages = []
            for user_msg, assistant_msg in history:
                messages.append({"role": "user", "content": user_msg})
                messages.append({"role": "assistant", "content": assistant_msg})
            messages.append({"role": "user", "content": message})
            return {"messages": messages}

        postprocess = lambda x: x  # No post-processing needed
    else:
        # Add other pipeline types when they will be needed
        raise ValueError(f"Unsupported pipeline type: {pipeline}")
    return inputs, outputs, preprocess, postprocess


def get_pipeline(model_name):
    # Determine the pipeline type based on the model name
    # For simplicity, assuming all models are chat models at the moment
    return "chat"


def registry(name: str, token: str | None = None, base_url: str | None = None, coder: bool = False, **kwargs):
    api_key = token or os.environ.get("HYPERBOLIC_API_KEY")
    if not api_key:
        raise ValueError("API key is not set. Please provide a token or set HYPERBOLIC_API_KEY environment variable.")

    if coder:
        interface = gr.Blocks(css="""
            .left_header {
                text-align: center;
                margin-bottom: 20px;
            }
            .right_panel {
                background: white;
                border-radius: 8px;
                overflow: hidden;
