                        "backstory": "Expert at analyzing questions and providing support",
                        "tasks": [
                            f"""Analyze this inquiry thoroughly: {topic}
                            Provide detailed support response."""
                        ]
                    },
                    {
                        "role": "Support Quality Assurance",
