import ollama
from ollama import Client, ResponseError

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, **kwargs):
    # Initialize Ollama client
    client = Client(host='http://localhost:11434')

    def predict(message, history, temperature=0.7, max_tokens=512):
        # Create a new list for history to avoid sharing between sessions
        history = list(history) if history else []

        # Format conversation history
        if isinstance(message, dict):
            message = message["text"]

        messages = []
        for user_msg, assistant_msg in history:
            messages.append({"role": "user", "content": user_msg})
            messages.append({"role": "assistant", "content": assistant_msg})
        messages.append({"role": "user", "content": message})

        try:
            # Stream the response
            stream = client.chat(
                model=model_name,
                messages=messages,
                stream=True,
                options={
                    "temperature": float(temperature),
                    "num_predict": max_tokens
                }
            )

            response_text = ""
            for chunk in stream:
                if chunk and "message" in chunk and "content" in chunk["message"]:
                    delta = chunk["message"]["content"]
                    response_text += delta
                    yield response_text

        except ResponseError as e:
            error_message = f"Error: {str(e)}"
            if e.status_code == 404:
                error_message += f"\nModel '{model_name}' not found. Try running: ollama pull {model_name}"
            yield error_message

    return predict

def get_interface_args(pipeline):
    if pipeline == "chat":
        def preprocess(message, history):
            return {"message": message, "history": history}

        def postprocess(response):
            return response

        return None, None, preprocess, postprocess
    else:
        raise ValueError(f"Unsupported pipeline type: {pipeline}")

def get_pipeline(model_name):
    return "chat"

def registry(name: str = None, **kwargs):
    if name and ':' in name:
        # Extract just the model name after 'ollama:'
        name = name.split(':', 1)[1]

    if not name:
        raise ValueError("Model name must be provided")

    # Try to pull the model
    try:
        print(f"Ensuring model '{name}' is available...")
        ollama.pull(name)
        print(f"Successfully pulled/verified model '{name}'")
    except Exception as e:
        raise ValueError(f"Error pulling model '{name}': {str(e)}")

    pipeline = get_pipeline(name)
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, **kwargs)

    interface = gr.ChatInterface(
        fn=fn,
        additional_inputs=[
            gr.Slider(0, 1, 0.7, label="Temperature"),
            gr.Slider(1, 2048, 512, label="Max tokens"),
        ]
    )

    return interface

import os
from transformers import AutoModelForCausalLM, AutoTokenizer, BitsAndBytesConfig
import torch
import gradio as gr
from typing import Callable
from PIL import Image

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, **kwargs):
    device = "cuda" if torch.cuda.is_available() else "cpu"

    # Get the full model path
    if "/" in model_name:
        model_path = model_name
    else:
        model_mapping = {
            "tulu-3": "allenai/llama-tulu-3-8b",
            "olmo-2-13b": "allenai/OLMo-2-1124-13B-Instruct",
            "smolvlm": "HuggingFaceTB/SmolVLM-Instruct",
            "phi-4": "microsoft/phi-4",
            "moondream": "vikhyatk/moondream2",
        }
        model_path = model_mapping.get(model_name)
        if not model_path:
            raise ValueError(f"Unknown model name: {model_name}")

    # Load model and tokenizer
    tokenizer = AutoTokenizer.from_pretrained(model_path)

    if model_name == "moondream":
        model = AutoModelForCausalLM.from_pretrained(
            model_path,
            revision="2025-01-09",
            trust_remote_code=True,
            device_map={"": "cuda" if torch.cuda.is_available() else "cpu"}
        )
    elif device == "cuda":
        model = AutoModelForCausalLM.from_pretrained(
            model_path,
            device_map="auto",
            torch_dtype=torch.float16
        )
    else:
        model = AutoModelForCausalLM.from_pretrained(
            model_path,
            device_map="auto",
            torch_dtype=torch.float32
        )

    def predict(message, history, temperature=0.7, max_tokens=512, image=None):
        # Create a new list for history to avoid sharing between sessions
        history = list(history) if history else []

        if model_name == "moondream":
            if isinstance(message, dict):
                text = message["text"]
                # Get the first image from files if available
                files = message.get("files", [])
                image = files[0] if files else image  # Use provided image if no files

            if image is not None:
                # Ensure image is a PIL Image
                if not isinstance(image, Image.Image):
                    try:
                        image = Image.open(image)
                    except Exception as e:
                        return f"Error processing image: {str(e)}"

                # Generate response and return as a string
                response = model.query(image, text)["answer"]
                return response
            else:
                return "Please provide an image to analyze."

        # Format conversation history
        if isinstance(message, dict):
            message = message["text"]

        messages = []
        for user_msg, assistant_msg in history:
            messages.append({"role": "user", "content": user_msg})
            messages.append({"role": "assistant", "content": assistant_msg})
        messages.append({"role": "user", "content": message})

        # Convert to model format
        input_text = tokenizer.apply_chat_template(messages, tokenize=False)
        inputs = tokenizer(input_text, return_tensors="pt").to(device)

        # Generate response
        generation_config = {
            "input_ids": inputs["input_ids"],
            "max_new_tokens": max_tokens,
            "temperature": float(temperature),  # Ensure temperature is a float
            "do_sample": True,
            "pad_token_id": tokenizer.eos_token_id
        }

        outputs = model.generate(**generation_config)

        # For phi-4, extract only the new generated text
        if model_name == "phi-4":
            input_length = inputs["input_ids"].shape[1]
            generated_tokens = outputs[0][input_length:]
            response = tokenizer.decode(generated_tokens, skip_special_tokens=True)
        else:
            response = tokenizer.decode(outputs[0], skip_special_tokens=True)

        return response

    return predict

def get_interface_args(pipeline):
    if pipeline == "chat":
        def preprocess(message, history):
            return {"message": message, "history": history}

        def postprocess(response):
            return response

        return None, None, preprocess, postprocess
    elif pipeline == "vision-chat":
        def preprocess(message, history):
            return {"message": message, "history": history}

        def postprocess(response):
            return response

        return [gr.Textbox(label="Message"), gr.Image(type="pil")], None, preprocess, postprocess
    else:
        raise ValueError(f"Unsupported pipeline type: {pipeline}")

def get_pipeline(model_name):
    if model_name == "moondream":
        return "vision-chat"
    return "chat"

def registry(name: str = None, **kwargs):
    pipeline = get_pipeline(name)
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, **kwargs)

    if pipeline == "vision-chat":
        interface = gr.ChatInterface(
            fn=fn,
            additional_inputs=[
                gr.Slider(0, 1, 0.7, label="Temperature"),
                gr.Slider(1, 2048, 512, label="Max tokens"),
            ],
            multimodal=True  # Enable multimodal input
        )
    else:
        interface = gr.ChatInterface(
            fn=fn,
            additional_inputs=[
                gr.Slider(0, 1, 0.7, label="Temperature"),
                gr.Slider(1, 2048, 512, label="Max tokens"),
            ]
        )

    return interface

import os
import base64
from openai import OpenAI
import gradio as gr
from typing import Callable

__version__ = "0.0.1"

def get_image_base64(url: str, ext: str):
    with open(url, "rb") as image_file:
        encoded_string = base64.b64encode(image_file.read()).decode('utf-8')
    return "data:image/" + ext + ";base64," + encoded_string

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str):
    def fn(message, history):
        inputs = preprocess(message, history)
        client = OpenAI(
            api_key=api_key,
            base_url="https://api.x.ai/v1",
        )
        completion = client.chat.completions.create(
            model=model_name,
            messages=inputs["messages"],
            stream=True,
        )
        response_text = ""
        for chunk in completion:
            delta = chunk.choices[0].delta.content or ""
            response_text += delta
            yield postprocess(response_text)

    return fn

def handle_user_msg(message: str):
    if type(message) is str:
        return message
    elif type(message) is dict:
        if message["files"] is not None and len(message["files"]) > 0:
            ext = os.path.splitext(message["files"][-1])[1].strip(".")
            if ext.lower() in ["png", "jpg", "jpeg", "gif"]:
                encoded_str = get_image_base64(message["files"][-1], ext)
            else:
                raise NotImplementedError(f"Not supported file type {ext}")
            content = [
                {"type": "text", "text": message["text"]},
                {
                    "type": "image_url",
                    "image_url": {
                        "url": encoded_str,
                    }
                },
            ]
        else:
            content = message["text"]
        return content
    else:
        raise NotImplementedError

def get_interface_args(model_name: str):
    inputs = None
    outputs = None

    def preprocess(message, history):
        messages = [{"role": "system", "content": "You are Grok, a chatbot inspired by the Hitchhikers Guide to the Galaxy."}]
        files = None
        for user_msg, assistant_msg in history:
            if assistant_msg is not None:
                messages.append({"role": "user", "content": handle_user_msg(user_msg)})
                messages.append({"role": "assistant", "content": assistant_msg})
            else:
                files = user_msg

        if type(message) is str and files is not None:
            message = {"text": message, "files": files}
        elif type(message) is dict and files is not None:
            if message["files"] is None or len(message["files"]) == 0:
                message["files"] = files

        messages.append({"role": "user", "content": handle_user_msg(message)})
        return {"messages": messages}

    postprocess = lambda x: x  # No post-processing needed
    return inputs, outputs, preprocess, postprocess

def registry(name: str = "grok-beta", token: str | None = None, **kwargs):
    """
    Create a Gradio Interface for X.AI's Grok model.

    Parameters:
        - name (str): The name of the model (defaults to "grok-beta" or "grok-vision-beta")
        - token (str, optional): The X.AI API key
    """
    api_key = token or os.environ.get("XAI_API_KEY")
    if not api_key:
        raise ValueError("XAI_API_KEY environment variable is not set.")

    inputs, outputs, preprocess, postprocess = get_interface_args(name)
    fn = get_fn(name, preprocess, postprocess, api_key)

    # Always set multimodal=True
    kwargs["multimodal"] = True

    interface = gr.ChatInterface(fn=fn, **kwargs)

    return interface

from swarms import Agent
from swarm_models import OpenAIChat
import gradio as gr
from typing import Generator, List, Dict, Callable
import base64
import os

__version__ = "0.0.1"

def get_fn(model_name: str, preprocess: Callable, postprocess: Callable, api_key: str, agent_name: str = "Assistant"):
    def fn(message, history):
        inputs = preprocess(message, history)
        agent = create_agent(model_name, agent_name)

        try:
            for response in stream_agent_response(agent, inputs["message"]):
                yield postprocess(response)
        except Exception as e:
            yield postprocess({
                "role": "assistant",
                "content": f"Error: {str(e)}",
                "metadata": {"title": "❌ Error"}
            })

    return fn

def get_interface_args(pipeline):
    if pipeline == "chat":
        def preprocess(message, history):
            messages = []
            for user_msg, assistant_msg in history:
                if assistant_msg is not None:
                    messages.append({"role": "user", "content": user_msg})
                    messages.append({"role": "assistant", "content": assistant_msg})
            messages.append({"role": "user", "content": message})
            return {"message": message, "history": messages}

        def postprocess(response):
            return response

        return None, None, preprocess, postprocess
    else:
        raise ValueError(f"Unsupported pipeline type: {pipeline}")

def create_agent(model_name: str = None, agent_name: str = "Assistant", system_prompt: str = None):
    """Create a Swarms Agent with the specified model and configuration"""
    model = OpenAIChat(model_name=model_name) if model_name else OpenAIChat()

    return Agent(
        agent_name=agent_name,
        system_prompt=system_prompt or "You are a helpful AI assistant.",
        llm=model,
        max_loops=1,
        autosave=False,
        dashboard=False,
        verbose=True,
        dynamic_temperature_enabled=True,
        streaming_on=True,
        saved_state_path=f"{agent_name.lower()}_state.json",
        user_name="gradio_user",
        retry_attempts=1,
        context_length=200000,
        return_step_meta=False,
        output_type="string"
    )

def stream_agent_response(agent: Agent, prompt: str) -> Generator[Dict, None, None]:
    # Initial thinking message
    yield {
        "role": "assistant", 
        "content": "Let me think about that...",
        "metadata": {"title": "🤔 Thinking"}
    }

    try:
        # Get response from agent
        response = agent.run(prompt)

        # Stream final response
        yield {
            "role": "assistant",
            "content": response,
            "metadata": {"title": "💬 Response"}
        }

    except Exception as e:
        yield {
            "role": "assistant",
            "content": f"Error: {str(e)}",
            "metadata": {"title": "❌ Error"}
        }

def registry(name: str, token: str | None = None, agent_name: str = "Assistant", **kwargs):
    api_key = token or os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("API key is not set. Please provide a token or set OPENAI_API_KEY environment variable.")

    pipeline = "chat"  # Swarms only supports chat for now
    inputs, outputs, preprocess, postprocess = get_interface_args(pipeline)
    fn = get_fn(name, preprocess, postprocess, api_key, agent_name)

    interface = gr.ChatInterface(fn=fn, **kwargs)
    return interface
